@theme {
  --color-bg: #0f1524;
  --color-primary: #3b6fed;
  --font-display: "Inter", sans-serif;
  --breakpoint-3xl: 1920px;
}

/* genera automáticamente: bg-bg, text-primary, font-display, 3xl:... */

@layer components {
  .btn-primary {
    @apply px-4 py-2 rounded-md bg-red-600 text-white hover:bg-red-700 transition-colors;
  }
}

<button class="btn-primary">Guardar</button>
